  // ...
});
```

Additionally, if you are using worker-scoped fixtures to manage authentication, you can ensure isolation by using a unique identifier for each worker and saving the state to the project's output directory, as shown in the following example:

```typescript
// Use parallelIndex as a unique identifier for each worker.
const id = test.info().parallelIndex;
const fileName = path.resolve(test.info().project.outputDir, `.auth/${id}.json`);
